using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

// Train model at startup
builder.Services.AddSingleton<ModelTrainingService>();

var app = builder.Build();

// Train and save the model before accepting requests
var trainer = app.Services.GetRequiredService<ModelTrainingService>();
trainer.TrainAndEvaluate();

// Register the pooled prediction engine with the trained model
builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(trainer.ModelPath);

// Rebuild the service provider is not ideal; instead register pool before build
// Let's restructure — we need to train first, then register the pool.
// The correct approach: register pool from file path that will exist after training.
app.MapControllers();
app.Run();

